import {authorMarkup} from './author.js';
import {L,language,setLanguage,languageControl,translateDOM,translateText} from './locale.js';
import {rubric,scoreExam} from './scoring.js';
import {kitItems} from './kit-data.js';
import {commandGuide} from './command-guide.js';
import {labs,domains,phases,DOC,examLabIds} from './catalog.js';
import {elapsed,remaining,formatTime,parseReport,completeLab,makeSession,selectExamTask,navigateExam,examTaskStatus,examObjectiveResults,closeSession} from './core.js';
import {examTasks,objectives,EXAM_SECONDS,EXAM_VERSION,examPlanCoverage} from './exam.js';
const exercises=[...labs,...examTasks];
const KEY='rhcsa-lab-v1';
const fresh=()=>({version:1,session:null,history:[],vmChecks:[],journal:[]});
let registrationMode='closed';
let legacy=null;try{legacy=JSON.parse(localStorage.getItem(KEY))}catch{}
let state=fresh(),profile=null,revision=0,authMode='login',authBusy=false,authReady=false,syncStatus='Cargando perfil',saveTimer,saveRunning=false,dirty=false;
let agentToken='',agentConnected=false,agentPort=8765,agentBusy=false,agentMessage='',commandSearch='',commandArea='all';
let search='',filter='all',statusFilter='all',selected=null,toastTimer,modalFocus;
const detectedHost=/Win/i.test(navigator.platform)?'windows':/Mac/i.test(navigator.platform)?'macos':'linux';
const hostPlatform=()=>state.hostPlatform||detectedHost;
const pythonLauncher=()=>hostPlatform()==='windows'?'py -3':'python3';
const collectCommand=s=>`${pythonLauncher()} collect.py --attempt ${s.id} --labs ${s.labs.join(',')}`;
const app=document.querySelector('#app');
const paths={home:'Mi espacio',catalog:'Laboratorios',exam:'Simulacro',vms:'Mis máquinas',progress:'Mi progreso',journal:'Bitácora',resources:'Biblioteca',session:'Sesión de práctica',lab:'Laboratorio',commands:'Comandos completos',verification:'Verificación de VMs',accounts:'Cuentas y actividad'};
const icon=(name,cls='')=>{const p={terminal:'m5 6 6 6-6 6m9 0h5',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',book:'M4 3h6a3 3 0 0 1 3 3v15a4 4 0 0 0-4-2H4zM13 6a3 3 0 0 1 3-3h5v16h-5a4 4 0 0 0-3 2',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',server:'M4 3h16v7H4zM4 14h16v7H4zM7 6h.01M7 17h.01M11 6h6M11 17h6',chart:'M4 20V10m8 10V4m8 16v-6',note:'M5 3h10l4 4v14H5zM14 3v5h5M8 12h8M8 16h6',arrow:'M4 12h16m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4',play:'m8 4 12 8-12 8z',pause:'M8 5v14M16 5v14',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',chevron:'m9 5 7 7-7 7',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',close:'m6 6 12 12M6 18 18 6',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',flag:'M5 22V3h13l-3 5 3 5H5',help:'M9 9a3 3 0 1 1 5 2c-1 .5-2 1-2 3m0 3h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',reset:'M3 10a9 9 0 1 1 2 8M3 3v7h7',menu:'M4 6h16M4 12h16M4 18h16',mail:'M3 5h18v14H3zM3 5l9 8 9-8'};return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${p[name]||p.terminal}"/></svg>`};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,action,cls='primary',more='')=>`<button class="btn ${cls}" data-action="${action}" ${more}>${text}</button>`;
function syncLabel(text){syncStatus=text;const node=document.querySelector('#sync-status');if(node)node.textContent=text}
function stateForSync(){const value=JSON.parse(JSON.stringify(state));for(const a of [...value.history,...(value.session?[value.session]:[])])if(a.examVersion>=4){delete a.verification;delete a.score;}return value}
function persist(){if(!profile)return;dirty=true;syncLabel('Cambios pendientes');clearTimeout(saveTimer);saveTimer=setTimeout(()=>flushSync().catch(()=>{}),400)}
async function apiFetch(path,method='GET',data){const r=await fetch(path,{method,credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const out=await r.json();if(!r.ok)throw Error(out.error||'No se pudo completar la solicitud.');return out}
async function flushSync(){clearTimeout(saveTimer);if(!profile)return;if(saveRunning){while(saveRunning)await new Promise(r=>setTimeout(r,50));if(!dirty)return}
 if(!dirty)return;saveRunning=true;dirty=false;syncLabel('Guardando en tu perfil…');try{const result=await apiFetch('/api/state','PUT',{state:stateForSync(),revision});revision=result.revision;for(const h of state.history){const remote=result.state?.history.find(x=>x.id===h.id);if(remote&&h.examVersion>=4){h.verification=remote.verification;h.completed=remote.completed}}syncLabel('Guardado en tu perfil')}catch(e){dirty=true;syncLabel(e.message);throw e}finally{saveRunning=false}if(dirty)return flushSync();}
async function bootstrap(){try{const config=await apiFetch('/api/config');registrationMode=config.registration; }catch{}try{const result=await apiFetch('/api/me');profile=result.profile;state=result.state;revision=result.revision;syncStatus='Guardado en tu perfil'}catch(e){syncStatus=e.message}authReady=true;render()}
async function handleAuth(){if(authBusy)return;authBusy=true;const error=document.querySelector('#auth-error');try{const data={mode:authMode,username:document.querySelector('#profile-user').value,password:document.querySelector('#profile-password').value,inviteCode:document.querySelector('#profile-invite')?.value||''};const result=await apiFetch('/api/auth','POST',data);profile=result.profile;state=result.state;revision=result.revision;syncStatus='Guardado en tu perfil';render()}catch(e){if(error)error.textContent=e.message}finally{authBusy=false}}
function independence(){return 'Guía independiente de preparación. No es un examen oficial ni está afiliada, patrocinada o avalada por Red Hat. Los escenarios son originales y no contienen preguntas reales del examen. Red Hat, RHEL, RHCSA y EX200 son marcas de sus respectivos titulares. Los resultados de práctica no garantizan aprobación.'}
function loginView(){return `<main class="auth-page"><a class="brand" href="#home"><span class="brand-symbol">${icon('terminal')}</span><span>Linux<span class="brand-light">lab</span></span></a><section class="auth-card"><span class="eyebrow">TU ESPACIO PERSONAL DE PREPARACIÓN</span><h1>${authMode==='register'?'Crea tu perfil de estudio.':'Continúa tu preparación.'}</h1><p>Guarda tus prácticas, simulacros y bitácora en tu propio espacio. Cada persona tiene sus propios datos y sesiones de acceso.</p>${authReady?`<form id="profile-form"><label for="profile-user">Usuario</label><input id="profile-user" name="username" autocomplete="username" required minlength="3" maxlength="32" pattern="[A-Za-z0-9][A-Za-z0-9_.-]{2,31}" placeholder="Elige tu nombre de usuario"><label for="profile-password">Contraseña</label><input id="profile-password" name="password" type="password" autocomplete="${authMode==='register'?'new-password':'current-password'}" required minlength="12" maxlength="128" placeholder="Mínimo 12 caracteres">${authMode==='register'&&registrationMode==='invite'?'<label for="profile-invite">Código de invitación</label><input id="profile-invite" name="inviteCode" type="password" autocomplete="off" required>':''}<p id="auth-error" role="alert"></p>${authMode==='register'?'<p class="small muted">Conserva tu contraseña y exporta respaldos. No se solicita correo ni hay recuperación por correo.</p>':''}${btn(authMode==='register'?'Crear mi perfil':'Entrar a mi espacio','profile-auth','primary full')}</form><button class="btn text" data-action="auth-mode">${authMode==='register'?'Ya tengo un perfil. Iniciar sesión':registrationMode==='closed'?'Registro cerrado · contactar al administrador':'Crear un perfil nuevo'}</button>`:'<p>Cargando el acceso a tu espacio…</p>'}</section><aside class="auth-notice"><h2>Una guía para practicar.</h2><p>${independence()}</p><p>Rocky Linux 10 es el entorno de laboratorio. El registro lo controla el administrador. No uses una contraseña que ya utilices en otros servicios.</p>${authorMarkup()}</aside></main>`}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),5000)}
const completed=()=>new Set(state.history.flatMap(h=>h.completed||[]).filter(id=>labs.some(l=>l.id===id)));
const domain=id=>domains.find(d=>d[0]===id)?.[1]||id;
const date=n=>new Date(n).toLocaleDateString(language==='en'?'en-US':'es-DO',{day:'numeric',month:'short',year:'numeric'});
const totalTime=()=>state.history.reduce((a,h)=>a+(h.elapsed||0),0)+elapsed(state.session);
const route=()=>location.hash.slice(1).split('/')[0]||'home';
function navItem(id,ic,label){return `<a href="#${id}" aria-label="${label}" title="${label}" class="nav-item ${route()===id?'active':''}" ${route()===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='catalog'?`<small>${labs.length}</small>`:''}</a>`}
function render(){if(!profile){app.innerHTML=loginView();return}if(expire())return;const r=route();if(state.session?.mode==='exam'&&['catalog','lab','resources','commands','accounts'].includes(r)){location.hash='session';toast('Los recursos de aprendizaje estarán disponibles al finalizar el simulacro.');return}app.innerHTML=`<aside class="sidebar"><a class="brand" href="#home" aria-label="RHCSA Lab: mi espacio"><span class="brand-symbol">${icon('terminal')}</span><span>Linux<span class="brand-light">lab</span><small>APRENDE. RESUELVE. REPITE.</small></span></a><div class="side-label">TU PREPARACIÓN</div><nav aria-label="Navegación principal">${navItem('home','grid','Mi espacio')}${navItem('catalog','terminal','Laboratorios')}${navItem('exam','clock','Simulacro')}${navItem('progress','chart','Mi progreso')}${profile.role==='admin'?navItem('accounts','grid','Cuentas y actividad'):''}<div class="nav-divider"></div><div class="side-label">TU LABORATORIO</div>${navItem('vms','server','Mis máquinas')}${navItem('journal','note','Bitácora')}${navItem('resources','book','Biblioteca')}${navItem('commands','terminal','Comandos completos')}${navItem('verification','server','Verificación de VMs')}</nav><div class="side-bottom"><div class="private-note">${icon('lock')} Espacio privado</div><div class="profile"><div class="avatar">${esc(profile.username.slice(0,2).toUpperCase())}</div><span>${esc(profile.username)}<small>EX200 · Rocky Linux 10</small></span><span class="online-dot" title="Espacio personal"></span></div></div></aside><div class="body"><header class="topbar"><span class="breadcrumb">Mi preparación <span>/</span> <strong>${paths[r]||'Laboratorio'}</strong></span><div class="top-actions"><span id="sync-status" class="sync-status">${esc(syncStatus)}</span>${btn('Salir','logout','text small')}<span class="release"><span></span> Rocky 10</span>${btn(icon('download')+' Respaldar','export','text small')}<span class="avatar small-avatar">${esc(profile.username.slice(0,2).toUpperCase())}</span></div></header><main id="main" tabindex="-1">${({home:home,catalog:catalog,exam:exam,vms:vms,progress:progress,journal:journal,resources:resources,session:sessionView,lab:labPreview,commands:commandsView,verification:verificationView,accounts:accountsView}[r]||home)()}</main><footer class="footer">${authorMarkup()}<span>Guía independiente de preparación · No es un examen oficial.</span><span>${btn('Aviso de independencia','independence','text small')}</span></footer></div>`;updateClock()}
function pageHeading(eyebrow,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function home(){const done=completed(),next=labs.find(l=>!done.has(l.id))||labs[0];const pct=Math.round(done.size/labs.length*100);return `${pageHeading('TU ESPACIO DE PRÁCTICA',`Hola, ${esc(profile.username)}<span class="accent">.</span>`,'La confianza se construye un laboratorio a la vez.',`<span class="date-chip">${icon('flag')} Objetivo: RHCSA EX200</span>`)}${legacy?.history?.length&&!state.history.length?`<div class="info-strip">Hay progreso anterior en este navegador. ${btn('Importarlo a este perfil','import-legacy','secondary small')}</div>`:''}<section class="hero"><div class="hero-copy"><span class="hero-kicker"><i></i> TU SIGUIENTE PASO</span><h2>Menos memorizar.<br>Más saber resolver.</h2><p>Dos máquinas. Retos reales. Un espacio para equivocarte, investigar y volver a intentarlo.</p><div class="hero-actions">${state.session?btn(icon('play')+' Continuar sesión','resume-route'):btn('Empezar una práctica '+icon('arrow'),'start-next')}<a href="#catalog" class="hero-link">Explorar laboratorios ${icon('chevron')}</a></div><div class="hero-meta"><span>${icon('check')} Pistas, sin soluciones</span><span>${icon('check')} A tu ritmo</span></div></div><div class="terminal-art" aria-label="Topología del laboratorio local"><div class="terminal-bar"><span><i></i><i></i><i></i></span><small>usuario@linux-lab: ~</small></div><div class="terminal-content"><p><b>~/lab</b> <span>$</span> tu entorno de práctica</p><div class="node"><span class="node-icon">${icon('server')}</span><div><strong>server<span>.lab</span></strong><small>192.168.56.10</small></div><em>Rocky 10</em></div><div class="connection"><span></span> red privada · host-only <span></span></div><div class="node"><span class="node-icon">${icon('terminal')}</span><div><strong>client<span>.lab</span></strong><small>192.168.56.20</small></div><em>Rocky 10</em></div><div class="terminal-foot"><i></i> VMs locales · verificación tras reiniciar</div></div></div></section><section class="stats" aria-label="Tu actividad"><div><span>Laboratorios completados</span><strong>${done.size}<small>/ ${labs.length}</small></strong><small>Resultados y evidencia registrados</small></div><div><span>Tiempo de práctica</span><strong>${Math.floor(totalTime()/3600000)}<small>h</small> ${Math.floor(totalTime()%3600000/60000)}<small>min</small></strong><small>Cada intento suma experiencia</small></div><div><span>Cobertura de tu ruta</span><strong>${pct}<small>%</small></strong><div class="bar"><i style="width:${pct}%"></i></div></div><div><span>Sesiones finalizadas</span><strong>${state.history.length.toString().padStart(2,'0')}</strong><small>${state.session?'Una sesión en curso':'Listo para tu siguiente intento'}</small></div></section><div class="section-title"><div><h2>Tu práctica, con intención</h2><p>Elige un punto de entrada. Tú decides el recorrido.</p></div><a href="#catalog">Ver los ${labs.length} laboratorios ${icon('arrow')}</a></div><div class="home-grid"><article class="recommend card"><div class="card-overline"><span class="badge">${state.session?'EN CURSO':'PARA CONTINUAR'}</span><span>${icon('clock')} ${next.minutes} min</span></div><div class="recommend-icon">${icon('terminal')}</div><h3>${state.session?'Vuelve a tu sesión':next.title}</h3><p>${state.session?'El reloj conserva el tiempo y tus notas. Retoma tu práctica donde la dejaste.':next.summary}</p><div class="recommend-bottom"><span>${domain(next.domain)}</span>${state.session?btn(icon('arrow'),'resume-route','icon-btn','aria-label="Continuar sesión"'):`<a class="btn icon-btn" href="#lab/${next.id}" aria-label="Abrir ${next.title}">${icon('arrow')}</a>`}</div></article><article class="card setup-card"><span class="box-icon">${icon('server')}</span><div><h3>Prepara el terreno</h3><p>Configura tus VMs client y server. El kit incluye Vagrantfile, guía y verificador local.</p><a href="#vms">Configurar mi laboratorio ${icon('arrow')}</a></div><span class="setup-count">${state.vmChecks.length}/6</span></article><article class="card exam-card"><div class="mini-title">${icon('clock')} MODO SIMULACRO</div><h3>¿Listo para ponerlo a prueba?</h3><p>120 minutos exactos. ${examLabs.length} retos. Puedes saltar y volver a cualquier ejercicio.</p><a href="#exam">Preparar un simulacro ${icon('arrow')}</a></article></div><section class="cycle-section"><div><span class="eyebrow">TU MÉTODO</span><h2>Aprender también es romper.</h2><p>Convierte cada incidente en criterio técnico.</p></div><div class="cycle">${phases.map((p,i)=>`<span><b>0${i+1}</b>${p}${i<5?icon('chevron'):''}</span>`).join('')}</div></section>`}
function labCard(l){const done=completed().has(l.id),attempted=state.history.some(h=>h.labs.includes(l.id));return `<article class="lab-card card"><div class="lab-card-head"><span class="domain-icon ${l.domain}">${icon(l.domain==='storage'||l.domain==='filesystems'?'server':l.domain==='security'?'lock':'terminal')}</span><span class="pill ${done?'success':''}">${done?'Completado':attempted?'Para reforzar':l.supplement?'Complemento':l.level}</span></div><div class="lab-domain">${domain(l.domain)}</div><h3>${l.title}</h3><p>${l.summary}</p><div class="lab-card-bottom"><span>${icon('clock')} ${l.minutes} min <i>·</i> ${l.machine==='ambas'?'2 VMs':l.machine}</span><a href="#lab/${l.id}" aria-label="Abrir ${l.title}">${icon(done?'check':'arrow')}</a></div></article>`}
function catalog(){return `${pageHeading('APRENDER HACIENDO','Laboratorios',`${labs.length} escenarios: 10 áreas de EX200 y un bloque adicional de Podman.`)}<div class="catalog-toolbar"><label class="searchbox">${icon('search')}<input type="search" id="search" placeholder="Buscar por tema, reto o herramienta…" value="${esc(search)}" aria-label="Buscar laboratorios"></label><select id="domain-filter" aria-label="Filtrar por área"><option value="all">Todas las áreas</option>${domains.map(d=>`<option value="${d[0]}" ${filter===d[0]?'selected':''}>${d[1]}</option>`).join('')}</select><select id="status-filter" aria-label="Filtrar por estado"><option value="all">Todos los estados</option><option value="pending" ${statusFilter==='pending'?'selected':''}>Pendientes</option><option value="done" ${statusFilter==='done'?'selected':''}>Completados</option></select></div><p class="muted small" id="result-count"></p><div class="lab-grid" id="lab-results"></div><div class="info-strip">${icon('help')} Los retos evalúan resultados. Algunos criterios se verifican con el informe local; otros requieren evidencia y autoevaluación explícita.</div>`}
function updateCatalog(){const done=completed(),q=search.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');const shown=labs.filter(l=>(filter==='all'||l.domain===filter)&&(statusFilter==='all'||done.has(l.id)===(statusFilter==='done'))&&(`${l.title} ${translateText(l.title)} ${l.summary} ${translateText(l.summary)} ${l.task} ${translateText(l.task)} ${domain(l.domain)} ${translateText(domain(l.domain))}`).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q));document.querySelector('#result-count').textContent=`${shown.length} laboratorio${shown.length!==1?'s':''} disponible${shown.length!==1?'s':''}`;document.querySelector('#lab-results').innerHTML=shown.length?shown.map(labCard).join(''):`<div class="empty"><h3>No hay coincidencias</h3><p>Prueba otro término o elimina los filtros.</p>${btn('Restablecer filtros','clear-filters','secondary')}</div>`}
function labPreview(){const l=labs.find(x=>x.id===location.hash.split('/')[1])||labs[0];return `<a class="backlink" href="#catalog">← Volver a laboratorios</a>${pageHeading(domain(l.domain),l.title,l.summary)}<div class="detail-grid"><section class="card content-card"><div class="detail-meta"><span>${icon('clock')} ${l.minutes} min</span><span>${icon('server')} ${l.machine}</span><span>${l.level}</span></div>${l.supplement?'<div class="scope-note">Extensión de administración y DevOps. Podman no aparece en los objetivos actuales de EX200/RHEL 10.</div>':''}<h2>Tu misión</h2>${l.prerequisite?`<div class="info-strip">${esc(l.prerequisite)}</div>`:''}<p class="task">${esc(l.task)}</p>${commandReference(l)}<h3>¿Cómo sabrás que está logrado?</h3><ol class="criteria-list">${l.criteria.map((c,i)=>`<li>${esc(c)}<small>${l.auto.includes(i)?'Verificación local':'Evidencia + autoevaluación'}</small></li>`).join('')}</ol><div class="info-strip">${icon('flag')} Los cambios deben sobrevivir al reinicio cuando el criterio lo indique.</div></section><aside class="detail-side"><div class="card content-card"><span class="eyebrow">PRÁCTICA GUIADA</span><h3>Un reto. Seis perspectivas.</h3><p>Consulta recursos, prueba, provoca una avería controlada y documenta lo que aprendiste.</p>${btn(icon('play')+' Iniciar práctica','start-lab','primary full',`data-id="${l.id}"`)}<small class="muted">Pausa disponible. Progreso guardado en tu perfil.</small></div><div class="card content-card"><h3>Antes de empezar</h3><p>Prepara las VMs y un snapshot limpio. Los ejercicios se ejecutan en tu terminal local.</p><a href="#vms">Ir a mis máquinas ${icon('arrow')}</a></div></aside></div>`}
const examLabs=examLabIds;
function coverageMatrix(result=null){const rows=result||examPlanCoverage();return `<div class="coverage-matrix">${domains.filter(d=>d[0]!=='containers').map(d=>{const entries=rows.filter(o=>o.domain===d[0]);return `<details><summary>${d[1]} <span>${result?entries.filter(o=>o.complete).length+'/':''}${entries.length} objetivos</span></summary><ul>${entries.map(o=>`<li><b>${o.id}</b><span>${esc(o.title)}<small>${o.tasks.map(id=>{const t=exercises.find(x=>x.id===id);return `${String(examLabs.indexOf(id)+1).padStart(2,'0')} · ${esc(t?.title||id)}`}).join(' / ')}</small></span>${result?`<em class="${o.complete?'covered':''}">${o.complete?'Con evidencia':'Por reforzar'}</em>`:''}</li>`).join('')}</ul></details>`}).join('')}</div>`}
function exam(){return `${pageHeading('COBERTURA COMPLETA · DOS HORAS','Simulacro integral EX200','32 retos específicos que recorren los 62 objetivos de estudio que compartiste.')}<div class="exam-intro"><section class="exam-main card"><div class="eyebrow">EX200 / RHEL 10 · entorno práctico Rocky 10</div><h2>Todos los objetivos.<br>El orden lo decides tú.</h2><p>Una sesión de entrenamiento de <strong>02:00:00 exactas</strong>, con ${examLabs.length} retos breves y los ${objectives.length} objetivos distribuidos en las 10 áreas. Incluye tar con gzip y bzip2, Flatpak, scripts, arranque, LVM, NFS/autofs, programación, red, usuarios, firewall y SELinux.</p><div class="exam-rules"><div>${icon('clock')}<strong>120 minutos</strong><span>Una fecha límite fija, incluso al cerrar o recargar.</span></div><div>${icon('arrow')}<strong>Salta y vuelve</strong><span>Siguiente, anterior, revisar y acceso directo a cualquier reto.</span></div><div>${icon('lock')}<strong>Sin pausa ni pistas</strong><span>Los resultados y las referencias se revisan al finalizar.</span></div></div>${state.session?btn('Volver a la sesión en curso '+icon('arrow'),'resume-route'):btn('Iniciar simulacro de 2 horas '+icon('arrow'),'confirm-exam')}<p class="small muted">Es la duración de entrenamiento solicitada. Los minutos sugeridos por reto suman 120, pero no bloquean tu navegación ni reservan tiempo individual. La cobertura del temario y el resultado comprobado de un intento son medidas distintas.</p><details class="exam-preflight" open><summary>Prepara el entorno antes de iniciar el reloj</summary><ul><li>Dos VMs con consola y SSH; extra_disks habilitado: dos discos vacíos en server y uno en client.</li><li>Kit actualizado, agent.py iniciado en el host y emparejado en Verificación de VMs antes del intento. Guarda snapshots limpios y una vía de recuperación por consola.</li><li>Paquetes base, repositorios e Internet disponibles. Puedes descargar previamente runtimes e imágenes Flatpak; la instalación/retirada de prueba se evidencia durante el reto.</li><li>Los retos de arranque, almacenamiento y red pueden interrumpir servicios. Puedes realizarlos en el orden que prefieras y volver a sus dependencias.</li></ul><a href="#vms">Preparar mis máquinas ${icon('arrow')}</a></details></section><aside class="card content-card exam-route"><h3>32 retos · 120 minutos orientativos</h3><ol class="exam-list">${examLabs.map(id=>{const l=exercises.find(x=>x.id===id);return `<li><span>${esc(l.title)}</span><small>${domain(l.domain)} · ${l.minutes} min · ${l.objectives.length} objetivo${l.objectives.length===1?'':'s'}</small></li>`}).join('')}</ol></aside></div><section class="card content-card"><div class="section-title"><div><span class="eyebrow">MAPA DE COBERTURA</span><h2>62 de 62 objetivos incluidos</h2><p>Cada punto de tu lista está asociado a uno o más retos. Abre un área para comprobar el recorrido.</p></div><a href="/lab/SIMULACRO_120_MIN.md" download>Descargar mapa y requisitos ${icon('download')}</a></div>${coverageMatrix()}<p class="small muted">El CDN de Red Hat es específico de RHEL. En Rocky se ejercitan las vías de repositorio remoto y RPM local que permite ese objetivo, explicando la diferencia. Podman conserva su bloque complementario en el catálogo.</p></section>`}
function start(ids,mode){if(agentBusy){toast('Espera a que termine la validación de las VMs.');return}if(state.session){toast('Ya hay una sesión activa. Finalízala antes de iniciar otra.');location.hash='session';return}const now=Date.now(),duration=exercises.find(l=>l.id===ids[0]).minutes;state.session=makeSession(ids,mode,now,crypto.randomUUID(),duration);selected=ids[0];persist();location.hash='session';render()}
function work(l){const s=state.session;return s.work[l.id]??=( {phase:1,hints:0,notes:'',evidence:{},manual:{},checks:{}})}
function currentLab(){const s=state.session;const id=s?.labs.includes(s.selectedLab)?s.selectedLab:s?.labs.includes(selected)?selected:s?.labs[0];return exercises.find(l=>l.id===id)}
const taskStateLabel={pending:'Pendiente',working:'Visitado',review:'Revisar',ready:'Preparado'};
function examNavigation(s,l){const statuses=s.labs.map(id=>examTaskStatus(s,id));return `<aside class="session-nav card"><h3>Retos <span>${s.labs.length}</span></h3><div class="exam-nav-counts"><span>${statuses.filter(x=>x==='ready').length} preparados</span><span>${statuses.filter(x=>x==='review').length} para revisar</span></div><div class="exam-task-list">${s.labs.map((id,i)=>{const status=examTaskStatus(s,id);return `<button class="task-nav ${l.id===id?'active':''} ${status}" data-action="select-lab" data-id="${id}" ${l.id===id?'aria-current="step"':''}><b>${String(i+1).padStart(2,'0')}</b><span>${esc(exercises.find(x=>x.id===id).title)}<small>${taskStateLabel[status]}</small></span></button>`}).join('')}</div></aside>`}
function examControls(s,l){const w=work(l),i=s.labs.indexOf(l.id);return `<div class="exam-controls"><div class="exam-position"><span>RETO ${i+1} DE ${s.labs.length}</span><strong>${l.minutes} min orientativos</strong><small>${l.objectives?.length||0} objetivo${l.objectives?.length===1?'':'s'} · ${taskStateLabel[examTaskStatus(s,l.id)]}</small></div><label class="exam-jump">Ir al reto<select id="exam-jump" aria-label="Ir al reto">${s.labs.map((id,j)=>`<option value="${id}" ${id===l.id?'selected':''}>${j+1}. ${esc(exercises.find(x=>x.id===id).title)}</option>`).join('')}</select></label><div class="exam-step-buttons">${btn('← Anterior','exam-previous','secondary small')}${btn('Omitir por ahora','exam-skip','secondary small')}${btn(i===s.labs.length-1?'Volver al primer reto →':'Siguiente →','exam-next','primary small')}</div><div class="exam-mark-buttons">${btn(icon('flag')+(w.review?' Quitar marca de revisión':' Marcar para revisar'),'exam-review','text small')}${btn(icon('check')+(w.ready?' Quitar preparado':' Marcar como preparado'),'exam-ready','text small')}</div><p>Preparado es una marca personal: no acredita un resultado técnico. Puedes pasar a otro reto con criterios pendientes; tu evidencia se conserva.</p></div>`}
function sessionView(){const s=state.session;if(!s)return `<div class="empty card">${icon('terminal')}<h1>Aquí empieza tu próxima práctica</h1><p>Elige un laboratorio o inicia un simulacro.</p><a class="btn primary" href="#catalog">Explorar laboratorios ${icon('arrow')}</a></div>`;const l=currentLab(),w=work(l),exam=s.mode==='exam',hasAuto=s.labs.some(id=>exercises.find(x=>x.id===id).auto.length>0);return `<div class="session-header"><div><div class="eyebrow">${exam?(s.examVersion===EXAM_VERSION?'SIMULACRO INTEGRAL · 02:00:00 · SIN PAUSA':'SIMULACRO · FORMATO ANTERIOR'):'PRÁCTICA GUIADA'} <span class="status-dot ${s.status==='paused'?'paused':''}"></span> ${s.status==='paused'?'EN PAUSA':'EN CURSO'}</div><h1>${exam?'Resuelve con autonomía.':l.title}</h1></div><div class="timer-area"><div><small>TIEMPO RESTANTE</small><strong id="clock" role="timer" aria-label="Tiempo restante">${formatTime(remaining(s))}</strong></div>${!exam?btn(icon(s.status==='paused'?'play':'pause'),s.status==='paused'?'unpause':'pause','secondary icon-btn',`aria-label="${s.status==='paused'?'Reanudar':'Pausar'}"`):'<span class="pill">Sin pausa</span>'}${btn('Finalizar','finish','secondary small')}</div></div>${exam&&s.examVersion!==EXAM_VERSION?'<div class="warning">Esta sesión pertenece al formato anterior. Finalízala para conservar su evidencia e iniciar el nuevo simulacro de 32 retos y dos horas.</div>':''}${s.status==='paused'?`<section class="empty card paused-panel">${icon('pause')}<h2>Haz una pausa. Tu avance está aquí.</h2><p>El reloj está detenido. Reanuda para continuar el reto.</p>${btn(icon('play')+' Reanudar práctica','unpause')}</section>`:`<div class="session-layout">${exam?examNavigation(s,l):''}<section class="session-main">${exam?examControls(s,l):''}<div class="phase-tabs" role="tablist" aria-label="Ciclo de práctica">${(exam?[1,5]:[0,1,2,3,4,5]).map(i=>`<button role="tab" aria-selected="${w.phase===i}" class="${w.phase===i?'active':''}" data-action="phase" data-phase="${i}"><span>0${i+1}</span>${phases[i]}</button>`).join('')}</div><article class="card content-card"><div class="card-overline"><span class="badge">${domain(l.domain)}</span><span>${icon('server')} ${l.machine}</span></div>${exam?`<h2>${l.title}</h2>${l.objectives?`<div class="exam-objectives">${l.objectives.map(id=>`<span title="${esc(objectives.find(o=>o.id===id).title)}">${id}</span>`).join('')}</div>`:''}`:''}${phaseContent(l,w,exam)}</article>${exam&&s.examVersion>=4?directEvidence(l,w):`<article class="card content-card evidence-card"><div class="section-title compact"><div><h2>Evidencia y resultados</h2><p>${exam?'Los resultados permanecerán ocultos hasta finalizar.':'Comprueba el estado real de tu trabajo en las VMs.'}</p></div>${hasAuto?btn(icon('upload')+' Importar informe','import-report','secondary small'):''}</div>${hasAuto?`<details class="report-help"><summary>Cómo obtener el informe de esta sesión</summary><p>Desde la carpeta del kit en tu equipo, ejecuta el recolector. Solo lee las VMs y genera un JSON; no envía datos por la red a esta web.</p><div class="codeblock"><code>${collectCommand(s)}</code>${btn('Copiar','copy-command','text small')}</div><p>Importa informe-ex200.json. Los criterios de evidencia se completan abajo. <a href="#vms">Ver kit y preparación</a></p></details>`:'<div class="info-strip">Este reto se evalúa con evidencia y autoevaluación. No requiere importar un informe local. Documenta las pruebas de cada criterio.</div>'}${l.criteria.map((c,i)=>{const auto=l.auto.includes(i),check=w.checks?.[i],manual=w.manual?.[i]&&String(w.evidence?.[i]||'').trim().length>=20;return `<div class="criterion ${!exam&&(auto?check?.pass:manual)?'passed':''}"><div class="criterion-heading"><span class="criterion-num">${!exam&&(auto?check?.pass:manual)?icon('check'):i+1}</span><div><strong>${esc(c)}</strong><small>${auto?'Verificación local · '+(exam?(check?'Informe recibido':'Pendiente de informe'):check?(check.pass?'Cumple el control automático':'Revisar en la VM'):'Pendiente de informe'):'Evidencia + autoevaluación'}</small></div></div>${auto?(check&&!exam?`<p class="check-detail">${esc(check.detail)} <span>· ${esc(check.machine)} · ${date(check.at)}</span></p>`:''):`<label class="evidence-label" for="evidence-${i}">Evidencia observada (mínimo 20 caracteres)</label><textarea id="evidence-${i}" data-evidence="${i}" placeholder="Qué comprobaste, salida relevante y resultado observado…" rows="2">${esc(w.evidence?.[i]||'')}</textarea><label class="checkbox-row"><input type="checkbox" data-manual="${i}" ${w.manual?.[i]?'checked':''}> Confirmo que comprobé este criterio en la VM</label>`}</div>`}).join('')}</article>`}</section><aside class="feedback-side"><section class="card content-card"><span class="eyebrow">${exam?'FOCO EN EL RETO':'RETROALIMENTACIÓN'}</span><h3>${exam?'Tu trabajo, tu criterio.':'Una pista a la vez.'}</h3><p>${exam?'Podrás revisar pistas y resultados cuando finalices. El tiempo sigue contando aunque cambies de pantalla.':'Primero observa. Después formula una hipótesis. Cada pista te orienta sin resolver el reto.'}</p>${!exam?`${Array.from({length:w.hints},(_,i)=>`<div class="hint"><b>PISTA ${i+1}</b><p>${esc(l.hints[i])}</p></div>`).join('')}${btn(w.hints>=3?'Todas las pistas visibles':'Ver pista '+(w.hints+1),'hint','secondary full',w.hints>=3?'disabled':'')}`:''}</section><section class="card content-card session-save">${icon('lock')}<h3>Tu avance se guarda</h3><p>En tu perfil personal, incluso al cambiar de equipo. Puedes exportar un respaldo adicional.</p><small>ID de sesión</small><code class="attempt-id">${s.id}</code></section>${!exam?`<section class="feedback-summary card content-card"><h3>Tu siguiente comprobación</h3><p>${feedback(l,w)}</p>${btn('Evaluar avance','evaluate','text')}</section>`:''}</aside></div>`}`}
function commandsView(){return `${pageHeading('REFERENCIA PRÁCTICA','Comandos completos',`${commandGuide.length} ejemplos ejecutables con descripción, ámbito y manual.`)}<div class="info-strip">Los ejemplos usan rutas de demostración. Se ejecutan por separado en una VM de práctica y pueden requerir archivos o paquetes previos. No forman una solución del simulacro. Comprueba el manual instalado en tu versión.</div><section class="card content-card"><label for="command-search">Buscar comando o descripción</label><input type="search" id="command-search" value="${esc(commandSearch)}" placeholder="tar, systemctl, SELinux…"><label for="command-area">Área</label><select id="command-area"><option value="all">Todas las áreas</option>${[...new Set(commandGuide.map(c=>c.area))].map(a=>`<option value="${esc(a)}" ${a===commandArea?'selected':''}>${esc(a)}</option>`).join('')}</select><p><a href="/lab/COMANDOS_COMPLETOS.md" download>Descargar referencia para estudiar sin conexión</a> · <a href="#resources">Consultar manuales y biblioteca</a></p></section><div id="command-list"></div>`}
function updateCommands(){const node=document.querySelector('#command-list');if(!node)return;const list=commandGuide.map((c,i)=>({...c,index:i})).filter(c=>(commandArea==='all'||c.area===commandArea)&&`${c.area} ${translateText(c.area)} ${c.command} ${c.description} ${translateText(c.description)}`.toLowerCase().includes(commandSearch.toLowerCase()));node.innerHTML=list.length?list.map(c=>`<article class="card content-card command-example"><div class="card-overline"><span class="badge">${esc(c.area)}</span><span>${c.scope==='Host'?'Anfitrión':'Dentro de la VM'}</span></div><div class="codeblock"><code>${esc(c.command)}</code>${btn('Copiar','copy-guide-command','secondary small',`data-index="${c.index}"`)}</div><p>${esc(c.description)}</p><p class="muted"><code>${esc(c.manual)}</code></p></article>`).join(''):'<div class="empty">No hay ejemplos que coincidan con tu búsqueda.</div>'}
function directEvidence(l,w){return `<article class="card content-card evidence-card"><h2>Registro personal y evaluación directa</h2><div class="info-strip">El agente comprobará el estado real antes y después de reiniciar las dos VMs al cerrar el intento. Las marcas personales no acreditan configuraciones. Documenta ahora las acciones transitorias; después del cierre las notas quedan bloqueadas.</div>${l.criteria.map((c,i)=>`<div class="criterion"><div class="criterion-heading"><span class="criterion-num">${i+1}</span><div><strong>${esc(c)} <span class="points-tag">${criterionPoints(l.id,i)} ${L('puntos','points')}</span></strong><small>Se contrastará con la lectura de las VMs. La evidencia documental se identifica por separado.</small></div></div><label class="evidence-label" for="evidence-${i}">Evidencia de ejecución (para pasos transitorios, mínimo 20 caracteres)</label><textarea id="evidence-${i}" data-evidence="${i}" rows="2" placeholder="Comprobación, salida relevante, fecha y resultado; no incluyas contraseñas ni claves…">${esc(w.evidence?.[i]||'')}</textarea><label class="checkbox-row"><input type="checkbox" data-manual="${i}" ${w.manual?.[i]?'checked':''}> He documentado esta comprobación (marca personal)</label></div>`).join('')}</article>`}
function verificationPanel(s){const v=s.verification,pending=v?.status!=='compared';return `<section class="card content-card"><span class="eyebrow">LECTURA REAL · DOS VMS · PERSISTENCIA</span><h3>${pending?'Validación pendiente':'Recolecciones comparadas'}</h3><p>${pending?'El trabajo está cerrado. Falta recoger el estado, reiniciar las dos VMs y contrastar la segunda lectura. Aún no hay un resultado técnico confirmado.':'Las mismas dos VMs tienen nuevos identificadores de arranque. Cada control distingue configuración técnica y evidencia documental.'}</p>${v?.nodes?.length?`<div class="table-scroll"><table><thead><tr><th>VM</th><th>Misma VM</th><th>Nuevo arranque</th></tr></thead><tbody>${v.nodes.map(n=>`<tr><td>${n.role}</td><td>${n.sameMachine?'Sí':'No'}</td><td>${n.rebooted?'Sí':'No'}</td></tr>`).join('')}</tbody></table></div><details><summary>Identificadores de arranque recogidos</summary><pre class="observation">${esc(JSON.stringify({before:v.beforeCapturedAt,after:v.afterCapturedAt,nodes:v.nodes},null,2))}</pre></details>`:''}${pending?btn(agentBusy?'Validando…':agentConnected?'Recopilar, reiniciar ambas VMs y validar':'Conectar agente y validar','verify-vms','primary',`data-id="${s.id}" ${agentBusy?'disabled':''}`):''}<p class="small muted">La validación posterior no añade tiempo de resolución. Los cambios persistentes deben cumplir antes y después, con la misma huella. El primer estado recogido se conserva como referencia, incluso si reintentas la validación. Las acciones transitorias conservan su evaluación documental.</p></section>`}
function directResults(s){const verified=s.verification?.status==='compared',objectiveResult=examObjectiveResults(s,objectives,examTasks);openModal(`<span class="eyebrow">GUÍA INDEPENDIENTE · RESULTADOS DEL ENTRENAMIENTO</span><h2>${verified?'Revisa la evidencia de tu intento.':'El trabajo terminó. Falta validar las VMs.'}</h2>${verificationPanel(s)}${scorePanel(s)}<div class="result-big">${verified?s.completed.length:'—'}<span>${verified?'/ '+s.labs.length+' retos completos':'Resultado técnico pendiente'}</span></div><p>Tiempo de resolución: ${formatTime(s.elapsed)}. Este resultado no es una calificación oficial. Los criterios documentales incluyen tu autoevaluación y se identifican expresamente.</p>${verified?`<h3>${objectiveResult.filter(o=>o.complete).length} / ${objectives.length} objetivos con reto completado</h3>${coverageMatrix(objectiveResult)}`:''}<div class="results-list">${s.labs.map(id=>{const l=exercises.find(t=>t.id===id),w=s.work[id]||{};return `<details><summary>${s.completed.includes(id)?'✓':'○'} ${esc(l.title)} <span class="points-tag">${scoreExam(s).areas.flatMap(a=>a.tasks).find(t=>t.id===id)?.earned||0}/${rubric.flatMap(a=>a.tasks).find(t=>t.id===id)?.max||0} ${L('puntos','points')}</span></summary>${l.criteria.map((c,i)=>{const check=s.verification?.checks?.[id]?.[i],doc=check?.documentary,ok=doc?w.manual?.[i]&&String(w.evidence?.[i]||'').trim().length>=20:check?.pass&&(!check.requiresDocumentation||w.manual?.[i]&&String(w.evidence?.[i]||'').trim().length>=20);return `<p><strong>${ok?'✓':'○'} ${esc(c)} <span class="points-tag">${scoreExam(s).areas.flatMap(a=>a.tasks).find(t=>t.id===id)?.criteria[i]?.earned||0}/${criterionPoints(id,i)}</span></strong><br><span class="pill">${!check?'Pendiente':doc?'Documental · autoevaluación':check.pass?'Control técnico verificado':'Control técnico por reforzar'}${check?.requiresDocumentation?' + documentación requerida':''}</span></p><p>${esc(check?.detail||'Requiere recolección directa de las VMs.')}</p>${doc||check?.requiresDocumentation?`<p class="preserve">${esc(w.evidence?.[i]||'Sin evidencia documental registrada antes del cierre.')}</p>`:''}${check?.observations?`<details><summary>Observaciones recogidas en las VMs</summary><pre class="observation">${esc(JSON.stringify(check.observations,null,2))}</pre></details>`:''}`}).join('')}<h4>Bitácora del intento</h4><p class="preserve">${esc(w.notes||'Sin diagnóstico documentado; se requieren 30 caracteres para completar el reto.')}</p><h4>Para investigar</h4>${readingList(l)}<p>${esc(l.hints[0])}</p></details>`}).join('')}</div><div class="modal-actions">${btn('Cerrar resultados','close-modal')}${btn('Exportar respaldo','export','secondary')}</div>`)}
function verificationView(){const attempts=state.history.filter(h=>h.mode==='exam'&&h.examVersion>=4);return `${pageHeading('CONEXIÓN CON TU LABORATORIO','Verificación de las dos VMs','Recopila hechos del sistema y comprueba que la configuración sobrevive a un reinicio normal.')}<section class="card content-card"><h2>1. Inicia el agente en tu equipo</h2><p>Descarga y descomprime el kit actualizado en la carpeta donde administras server y client. Con las VMs encendidas, ejecuta en ${hostGuides[hostPlatform()].terminal}:</p><div class="codeblock"><code>${pythonLauncher()} agent.py --site ${esc(location.origin)}</code></div><p>El agente solo escucha en 127.0.0.1. Copia aquí el código temporal que imprime tu terminal. Se mantiene en memoria de esta pestaña; vuelve a emparejar al recargar. No expongas SSH ni el agente a Internet.</p><a href="/lab/rhcsa-lab-kit.zip" class="btn secondary" download>Descargar kit actualizado</a> <a href="/lab/AGENTE_LOCAL.md" download>Leer guía del agente</a></section><section class="card content-card"><h2>2. Empareja esta pestaña</h2><p>Abre la URL privada en una pestaña completa de Chrome o Edge de escritorio actualizado. Si el navegador solicita acceso a la red local, permítelo para este sitio. Los navegadores que bloqueen HTTPS → loopback no podrán conectar este agente; usa uno compatible.</p><form id="agent-form"><label for="agent-code">Código temporal de tu terminal</label><input id="agent-code" type="password" autocomplete="off" spellcheck="false" placeholder="64 caracteres del agente" required pattern="[a-f0-9]{64}" ${agentBusy?'disabled':''}><label for="agent-port">Puerto local</label><input id="agent-port" type="number" min="1024" max="65535" value="${agentPort}" required ${agentBusy?'disabled':''}><div class="modal-actions"><button class="btn primary" type="submit" ${agentBusy?'disabled':''}>${agentConnected?'Volver a emparejar':'Conectar con mi agente'}</button>${agentConnected?btn('Desconectar','disconnect-agent','secondary',agentBusy?'disabled':''):''}</div></form><p id="agent-status" role="status" aria-live="polite">${esc(agentMessage|| (agentConnected?'Agente emparejado con server y client.':'Esperando emparejamiento.'))}</p></section><section class="card content-card"><h2>3. Valida el intento terminado</h2><p>Al pulsar validar se realiza una lectura por SSH de <strong>server y client</strong>, se guarda la referencia, se ejecuta <code>vagrant reload</code> en cada nodo y se recogen ambos otra vez. Solo se acredita persistencia con la misma identidad de máquina, otro boot ID y los mismos ajustes requeridos. La sonda ejecuta lecturas y pruebas funcionales acotadas, sin reparar configuraciones.</p><p>Los dos nodos se recogen aunque no hayas marcado tareas como preparadas. Si uno falla, el intento permanece pendiente. Documenta antes de cerrar los pasos transitorios, que el estado final no puede demostrar por sí solo.</p>${state.session?.mode==='exam'?'<div class="info-strip">El simulacro sigue en curso. La validación estará disponible al finalizar; el reloj continúa.</div>':''}${attempts.length?attempts.map(h=>`<article class="verification-attempt"><h3>${date(h.finishedAt)} · ${formatTime(h.elapsed)}</h3><code class="attempt-id">${h.id}</code>${verificationPanel(h)}</article>`).join(''):'<p>Tus nuevos simulacros finalizados aparecerán aquí. Los intentos del formato anterior conservan sus resultados originales y no se presentan como verificados tras reiniciar.</p>'}<p class="small muted">Recomendación: valida inmediatamente al cerrar el intento. Si haces cambios antes de la primera lectura, la guía no puede demostrar cuándo los hiciste; esto es preparación personal y no un sistema de examen supervisado.</p></section>`}
async function agentFetch(path,body){const response=await fetch(`http://127.0.0.1:${agentPort}${path}`,{method:body?'POST':'GET',mode:'cors',credentials:'omit',targetAddressSpace:'loopback',headers:{'X-Linux-Lab-Token':agentToken,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(path==='/status'?45000:15000)});const data=await response.json();if(!response.ok)throw Error(data.error||'No se pudo conectar con el agente.');return data}
function agentStatus(message){agentMessage=message;const el=document.querySelector('#agent-status');if(el)el.textContent=message}
async function pairAgent(){const input=document.querySelector('#agent-code'),port=document.querySelector('#agent-port');if(!input?.checkValidity()||!port?.checkValidity())return;agentToken=input.value.trim();agentPort=Number(port.value);input.value='';try{agentStatus('Conectando con el agente local…');const status=await agentFetch('/status');if(!status.ready||status.version!==1)throw Error('Actualiza el kit del agente.');agentConnected=true;agentStatus('Agente conectado. server y client se leerán al validar un intento.');toast('Agente emparejado.')}catch(e){agentConnected=false;agentToken='';agentStatus('No se pudo emparejar. Comprueba el agente, el código y el permiso de red local del navegador. '+e.message)}}
async function localJob(body){const {jobId}=await agentFetch('/jobs',body);for(let n=0;n<1500;n++){await new Promise(resolve=>setTimeout(resolve,1000));const job=await agentFetch('/jobs/'+jobId);agentStatus(job.message);if(job.status==='done')return job.result;if(job.status==='failed')throw Error(job.message)}throw Error('La operación tardó demasiado. Comprueba la consola de las VMs antes de reintentar.')}
async function saveVmReport(attempt,phase,report){const result=await apiFetch('/api/evidence','POST',{attemptId:attempt.id,phase,report});Object.assign(attempt,result.attempt);revision=result.revision;return result}
async function verifyAttempt(attempt){if(!attempt||agentBusy)return;if(!agentConnected){location.hash='verification';render();toast('Inicia el agente y empareja esta pestaña para validar.');return}agentBusy=true;location.hash='verification';render();try{await flushSync();agentStatus('Recogiendo referencia de las dos VMs…');const before=await localJob({action:'collect',attempt:attempt.id,labs:attempt.labs,phase:'before'});await saveVmReport(attempt,'before',before);agentStatus('Referencia guardada. Reiniciando normalmente ambas VMs…');await localJob({action:'reboot',attempt:attempt.id,confirm:true});const after=await localJob({action:'collect',attempt:attempt.id,labs:attempt.labs,phase:'after'});await saveVmReport(attempt,'after',after);agentStatus('Comparación terminada. Consulta los controles técnicos y documentales.');toast(attempt.verification.status==='compared'?'Las dos VMs fueron recogidas y sus reinicios comprobados.':'No se confirmó persistencia; revisa las identidades y arranques.')}catch(e){agentStatus('Validación pendiente: '+e.message);toast('No se confirmó la persistencia: '+e.message)}finally{agentBusy=false;render();directResults(attempt)}}

function feedback(l,w){const unverified=l.auto.find(i=>w.checks?.[i]?.pass!==true);if(unverified!==undefined)return `El criterio ${unverified+1} necesita una comprobación local satisfactoria. Importa un informe reciente y revisa el resultado en la VM.`;const manual=l.criteria.findIndex((_,i)=>!l.auto.includes(i)&&(!w.manual?.[i]||String(w.evidence?.[i]||'').trim().length<20));if(manual>=0)return `Aporta evidencia concreta del criterio ${manual+1} y confirma que lo comprobaste. Describe el resultado, no solo la intención.`;if(String(w.notes||'').trim().length<30)return 'Documenta al menos 30 caracteres sobre diagnóstico, reparación y comprobación final antes de cerrar el reto.';return 'Los criterios registrados están completos. Comprueba la persistencia cuando corresponda y finaliza para registrar el laboratorio.'}
function phaseContent(l,w,exam){switch(w.phase){case 0:return `<h2>Entiende antes de intervenir</h2><p>Investiga los conceptos que necesitas para este reto. Usa los manuales de tu VM para acostumbrarte a trabajar sin Internet.</p><div class="concept-card"><h3>Lo que necesitas comprender</h3><p>${esc(l.learning.concept)}</p></div>${readingList(l)}${commandReference(l)}<h3>Preguntas para investigar</h3><ul class="plain-list">${l.learning.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul><h3>Errores frecuentes</h3><ul class="plain-list">${l.learning.traps.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><div class="prompt-box"><strong>Pregunta de partida</strong><p>¿Qué estado necesitas conseguir y qué observación demostraría que lo lograste?</p></div>`;case 2:return `<h2>Romper, con un punto de retorno</h2><div class="warning">Solo en una VM desechable y después de un snapshot. No ejecutes averías en tu equipo anfitrión ni en producción.</div><p class="task">${esc(l.incident)}</p><p>No avances a reparar hasta haber descrito el síntoma y una hipótesis.</p>`;case 3:return `<h2>Diagnostica antes de cambiar</h2><div class="diagnosis-grid">${['¿Qué cambió?','¿Qué evidencia tienes?','¿En qué capa falla?','¿Cómo probarás tu hipótesis?'].map((t,i)=>`<div><b>0${i+1}</b><h3>${t}</h3><p>${['Compara el estado actual con el punto de control anterior.','Recoge un error reproducible, fecha y registros relevantes.','Distingue identidad, permisos, servicio, red y política de seguridad.','Cambia una sola variable y define el resultado esperado.'][i]}</p></div>`).join('')}</div>`;case 4:return `<h2>Repara y vuelve a comprobar</h2><p>Aplica el cambio mínimo que resuelva tu hipótesis. Repite la prueba original, una prueba negativa y el reinicio cuando corresponda.</p><ul class="plain-list"><li>¿Desapareció la causa o solo el síntoma?</li><li>¿Se mantiene el acceso de gestión y la seguridad?</li><li>¿Podrías repetir el procedimiento desde tu snapshot?</li></ul><p>Conserva en la bitácora el estado antes y después de la reparación.</p>`;case 5:return `<h2>Convierte el intento en conocimiento</h2><p>Documenta el síntoma, tu hipótesis, la evidencia, la causa, el cambio aplicado y la comprobación final. No incluyas contraseñas ni claves privadas.</p><label class="evidence-label" for="session-notes">Bitácora de este reto (mínimo 30 caracteres para completar)</label><textarea rows="10" id="session-notes" placeholder="Síntoma:\nHipótesis:\nEvidencia:\nCausa:\nReparación:\nPrueba final / reinicio:\nQué repetiría distinto:">${esc(w.notes)}</textarea><span class="autosave">Guardado automático en tu perfil</span>`;default:return `<h2>Tu misión</h2>${l.prerequisite?`<div class="info-strip">${esc(l.prerequisite)}</div>`:''}<p class="task">${esc(l.task)}</p>${!exam?commandReference(l):''}<div class="prompt-box">${icon('terminal')} Trabaja en tu terminal local. Esta web coordina el reto; el verificador lee el estado de tus VMs.</div>`}}
function commandReference(l){return `<details class="command-reference"><summary>Herramientas y comandos para investigar</summary><p>Los comandos de observación ayudan a recoger evidencia. Las plantillas contienen parámetros que tú debes decidir; no forman una solución ordenada del reto.</p><div class="table-scroll"><table class="command-table"><thead><tr><th>Comando o plantilla</th><th>Para qué sirve</th><th>Uso</th></tr></thead><tbody>${l.commands.map(([cmd,purpose,kind])=>`<tr><td><code>${esc(cmd)}</code></td><td>${esc(purpose)}</td><td><span class="pill">${kind==='plantilla'?'Plantilla':'Observar'}</span></td></tr>`).join('')}</tbody></table></div><p class="small">Los nombres en MAYÚSCULAS y las partes entre corchetes son referencias de sintaxis: no las ejecutes literalmente. Mantén la sección man como fuente principal.</p></details>`}
function readingList(l){return `<ul class="reading-list">${l.reading.map(r=>`<li>${icon('book')}${r.startsWith('http')?`<a href="${r}" target="_blank" rel="noopener">Documentación técnica ${icon('external')}</a>`:`<code>${esc(r)}</code><small>en la VM</small>`}</li>`).join('')}</ul>`}
function expire(){const s=state.session;if(s?.status==='running'&&remaining(s)===0){finishSession(true);return true}return false}
function finishSession(timedOut=false){const s=state.session;if(!s)return;closeSession(s,exercises,Date.now(),timedOut);state.history.unshift(s);state.session=null;persist();location.hash='progress';render();openResults(s);if(s.timedOut)toast(s.mode==='exam'&&s.examVersion===EXAM_VERSION?'Las dos horas terminaron. La entrega conserva la evidencia y marca los criterios pendientes.':'El tiempo terminó. Tu intento y evidencia quedaron guardados.')}
function openResults(s){if(s.mode==='exam'&&s.examVersion>=4)return directResults(s);const objectiveResult=s.mode==='exam'&&s.examVersion===EXAM_VERSION?examObjectiveResults(s,objectives,examTasks):null;openModal(`<span class="eyebrow">${s.timedOut?'TIEMPO FINALIZADO':'SESIÓN FINALIZADA'} · ${s.mode==='exam'?'SIMULACRO':'PRÁCTICA'}</span><h2>El intento también enseña.</h2><div class="result-big">${s.completed.length}<span>/ ${s.labs.length} retos completos</span></div><p>Tiempo utilizado: ${formatTime(s.elapsed)}. Estos resultados combinan controles locales y autoevaluación; no son una nota oficial.</p>${objectiveResult?`<section class="result-coverage"><h3>${objectiveResult.filter(o=>o.complete).length} / ${objectives.length} objetivos con reto completado</h3><p>El plan incluye los 62 objetivos. Este resultado solo cuenta los asociados a retos cuyos criterios y documentación quedaron satisfechos; no equivale a una calificación oficial.</p>${coverageMatrix(objectiveResult)}</section>`:''}<div class="results-list">${s.labs.map(id=>{const l=exercises.find(x=>x.id===id),w=s.work[id]||{};return `<details><summary><span class="pill ${s.completed.includes(id)?'success':''}">${s.completed.includes(id)?'Completo':'Por reforzar'}</span> ${l.title}</summary><p>${feedback(l,w)}</p>${l.criteria.map((c,i)=>{const ok=l.auto.includes(i)?w.checks?.[i]?.pass:w.manual?.[i]&&String(w.evidence?.[i]||'').trim().length>=20;return `<p class="small">${ok?'✓':'○'} ${esc(c)}<br><span class="muted">${l.auto.includes(i)?esc(w.checks?.[i]?.detail||'Sin informe local'):esc(w.evidence?.[i]||'Sin evidencia registrada')}</span></p>`}).join('')}<h4>Para investigar</h4>${readingList(l)}<p class="small">${esc(l.hints[0])}</p>${w.notes?`<h4>Tu bitácora</h4><p class="preserve">${esc(w.notes)}</p>`:''}</details>`}).join('')}</div><div class="modal-actions">${btn('Volver a mi progreso','close-modal','primary')}${btn('Exportar respaldo','export','secondary')}</div>`)}
const hostGuides={
windows:{label:'Windows',terminal:'PowerShell',prereq:'Instala VirtualBox y Vagrant para Windows, Python 3 con el lanzador py y OpenSSH Client. Ejecuta este kit desde PowerShell en Windows; evita mezclar Vagrant de WSL con el proveedor nativo.',commands:['vagrant --version','& "$env:ProgramFiles\\Oracle\\VirtualBox\\VBoxManage.exe" --version','py -3 --version','vagrant validate','vagrant up --provider=virtualbox'],note:'Usa una carpeta local fuera de OneDrive si aparecen bloqueos. Revisa VT-x/AMD-V y los logs de VirtualBox si otra plataforma de virtualización afecta el arranque; no cambies protecciones de Windows a ciegas.'},
macos:{label:'macOS',terminal:'Terminal',prereq:'Instala VirtualBox y Vagrant compatibles con tu macOS y Python 3. Este kit fija una imagen x86_64: corresponde a Mac Intel. Un Mac Apple Silicon necesita una imagen ARM64 y un proveedor compatibles; este archivo no emula x86.',commands:['VBoxManage --version','vagrant --version','python3 --version','vagrant validate','vagrant up --provider=virtualbox'],note:'En Mac Intel, comprueba que el hipervisor exponga x86-64-v3 a Rocky 10. Empieza con una VM si otras aplicaciones consumen recursos.'},
linux:{label:'Linux',terminal:'Bash',prereq:'Instala Vagrant, VirtualBox y Python 3 para tu distribución. Comprueba que el módulo de VirtualBox carga con tu kernel y que la CPU es x86_64 compatible con x86-64-v3 para Rocky 10.',commands:['VBoxManage --version','vagrant --version','python3 --version','vagrant validate','vagrant up --provider=virtualbox'],note:'No ejecutes Vagrant con sudo: crearía otro estado y otras claves. Si Secure Boot impide cargar un módulo, sigue el proceso de firma de tu distribución.'}
};
function vms(){const guide=hostGuides[hostPlatform()];const list=['VirtualBox, Vagrant y Python disponibles en mi sistema anfitrión.','Rocky 10 inicia y la CPU expone las instrucciones requeridas.','server y client tienen hostname, consola y SSH funcionales.','NAT proporciona Internet y la red privada comunica ambos nodos.','Discos de práctica habilitados e identificados si el reto los necesita.','Actualizaciones revisadas, reinicio completado y snapshot base guardado.'];return `${pageHeading('TU ENTORNO LOCAL','El mismo laboratorio, en tu equipo.','Rocky Linux 10 · VirtualBox · Windows, macOS Intel y Linux x86_64.',`<a class="btn primary" href="/lab/rhcsa-lab-kit.zip" download>${icon('download')} Descargar kit completo</a>`)}<div class="scope-note"><strong>Versión elegida: Rocky Linux 10.</strong> El examen sigue basado en RHEL 10. El kit incluye Vagrantfile.rocky9 como alternativa explícita a la referencia a Rocky 9; no mezcla versiones dentro de una sesión.</div><div class="vm-cards">${[['server','192.168.56.10','Servicios, almacenamiento, seguridad y Podman','2 discos de 8 GiB opcionales'],['client','192.168.56.20','Acceso remoto, pruebas de red, NFS y Flatpak','1 disco de 8 GiB opcional']].map(v=>`<article class="card vm-card"><div class="vm-card-top"><span class="box-icon">${icon(v[0]==='server'?'server':'terminal')}</span><span class="pill">Rocky Linux 10 · Local</span></div><h2>${v[0]}<span>.lab</span></h2><code>${v[1]} /24</code><p>${v[2]}</p><div class="vm-specs"><span>1 vCPU</span><span>1 GiB RAM</span><span>25 GiB virtuales</span></div><small>${v[3]} · extra_disks: false por defecto</small></article>`).join('')}</div><div class="detail-grid"><section><article class="card content-card"><h2>Prepara tu sistema anfitrión</h2><div class="platform-tabs" role="tablist" aria-label="Sistema anfitrión">${Object.entries(hostGuides).map(([id,g])=>`<button role="tab" aria-selected="${hostPlatform()===id}" class="${hostPlatform()===id?'active':''}" data-action="platform" data-host="${id}">${g.label}</button>`).join('')}</div><h3>${guide.terminal}</h3><p>${guide.prereq}</p><div class="codeblock host-code"><code>${guide.commands.map(esc).join('<br>')}</code></div><p>${guide.note}</p><p class="small"><a href="https://www.virtualbox.org/wiki/Downloads" target="_blank" rel="noopener">VirtualBox</a> · <a href="https://developer.hashicorp.com/vagrant/install" target="_blank" rel="noopener">Vagrant</a> · <a href="https://www.python.org/downloads/" target="_blank" rel="noopener">Python</a></p></article><article class="card content-card"><h2>Un Vagrantfile para entender y modificar</h2><p>La imagen oficial está fijada por URL y SHA-256. La base se descarga al ejecutar Vagrant: ya no necesitas construir una box RHEL ni una suscripción para este laboratorio.</p><details class="vagrant-details"><summary>Ver Vagrantfile comentado</summary><pre class="vagrant-source"><code id="vagrant-source">Cargando archivo…</code></pre><div class="modal-actions">${btn('Copiar Vagrantfile','copy-vagrant','secondary small')}<a class="btn text small" href="/lab/Vagrantfile" download>Descargar archivo</a></div></details><h3>Arquitectura elegida</h3><p>Dos VMs iguales en recursos, con funciones diferentes. NAT usa DHCP para Internet; la interfaz host-only usa IP fija para que SSH, NFS y las comprobaciones no cambien de destino. No hay bridge ni carpetas compartidas: el verificador se copia por SSH.</p><h3>Por qué UTC</h3><p>UTC permite comparar registros entre nodos y estudiantes en distintos países sin conversiones ni cambios estacionales. Puedes cambiar timezone a America/Montevideo en el bloque LAB si deseas practicar con esa zona.</p><h3>Ventajas para preparar RHCSA</h3><p>Acceso a systemd, DNF, LVM, SELinux, firewalld y dos extremos de una conexión. Rocky sirve como entorno práctico; las suscripciones y CDN específicos de Red Hat deben estudiarse en su documentación oficial.</p><h3>Mejoras futuras posibles</h3><p>Habilitar discos vacíos, ampliar RAM a 2048 MiB para cargas pesadas, crear snapshots por módulo y mantener otra box fijada para comparar versiones. Cambia una variable a la vez y registra el efecto.</p><div class="warning">1 GiB es el perfil base solicitado, no una garantía para cualquier carga. DNF, runtimes Flatpak y Podman pueden necesitar más memoria. El disco virtual se amplía a 25 GiB; particiones y filesystem pueden conservar el tamaño original y deben comprobarse por separado. Vagrant no reduce discos existentes.</div></article><article class="card content-card"><h2>Del primer arranque al primer reto</h2><ol class="setup-steps"><li><b>Descomprime el kit y revisa LAB</b><p>Mantén Vagrantfile, provision.sh y verify.py juntos. Para GPT/LVM/swap/FS cambia extra_disks a true antes de iniciar; server recibe dos discos vacíos de 8 GiB y client uno.</p></li><li><b>Inicia las dos VMs</b><div class="codeblock"><code>vagrant validate<br>vagrant up --provider=virtualbox<br>vagrant status</code></div><p>El provisioning actualiza paquetes, instala herramientas y prepara timezone, hostname y SSH. No resuelve los ejercicios. Si la actualización cambia el kernel, reinicia antes de guardar la base.</p></li><li><b>Comprueba y guarda un punto de retorno</b><div class="codeblock"><code>vagrant ssh server<br>vagrant ssh client<br>vagrant reload<br>vagrant snapshot save base-limpia</code></div><p>Dentro de cada VM revisa hostnamectl, timedatectl, ip -br address, lsblk y df -hT. Confirma Internet y comunicación entre nodos.</p></li><li><b>Practica y recoge evidencia</b><p>Inicia el reto en la web. Para una práctica guiada puedes importar su informe. Para el simulacro usa Verificación de VMs: recopila ambas VMs, reinicia y compara otra lectura automáticamente. La selección de sistema anfitrión también adapta el lanzador de Python.</p></li></ol><h3>Comandos básicos de Vagrant</h3><div class="table-scroll"><table class="command-table"><thead><tr><th>Comando</th><th>Qué hace</th></tr></thead><tbody>${[['vagrant up','Crea/inicia ambas VMs y aprovisiona en el primer arranque.'],['vagrant ssh server','Abre una shell SSH en server; usa client para el otro nodo.'],['vagrant halt','Apaga normalmente las VMs conservando discos y estado.'],['vagrant destroy','Elimina las VMs y sus discos asociados tras confirmación. No se deshace con vagrant up.'],['vagrant provision','Repite el provisionador; puede instalar nuevas actualizaciones.'],['vagrant reload','Reinicia y aplica cambios de hardware/red.']].map(([c,d])=>`<tr><td><code>${c}</code></td><td>${d}</td></tr>`).join('')}</tbody></table></div><h3>Errores comunes a evitar</h3><ul class="plain-list"><li>Ejecutar el provisionador dentro del host en vez de la VM.</li><li>Formatear el disco raíz al asumir que los discos se llaman sdb/sdc.</li><li>Mezclar estado de Rocky 9 y 10 o reemplazar una VM con trabajo sin exportarlo.</li><li>Añadir gateway privado y perder la salida NAT; usar una subred que ya ocupa la VPN.</li><li>Confundir tamaño del disco con tamaño de la raíz o recrear VMs para corregir un problema de permisos.</li></ul><details><summary>Alternativa Rocky Linux 9</summary><p>El archivo Vagrantfile.rocky9 conserva recursos y red con otra imagen oficial. Úsalo en una carpeta nueva y renómbralo Vagrantfile antes de crear las VMs. Rocky 9 tiene diferencias respecto de EX200/RHEL 10; no se presenta como una reproducción equivalente del examen.</p><a href="/lab/Vagrantfile.rocky9" download>Descargar alternativa Rocky 9</a></details><div class="info-strip">${icon('lock')} El agente local lee ambas VMs mediante Vagrant SSH y entrega las observaciones a tu perfil. No necesitas exponer SSH a Internet. El acceso del sitio sigue siendo privado; compartirlo con otra persona requiere una concesión de acceso aparte.</div></article></section><aside class="detail-side"><section class="card content-card"><h3>Checklist de preparación</h3><p class="small muted">${state.vmChecks.length} de 6 comprobaciones marcadas por ti</p><div class="bar"><i style="width:${state.vmChecks.length/6*100}%"></i></div>${list.map((t,i)=>`<label class="checkbox-row checklist"><input type="checkbox" data-vm="${i}" ${state.vmChecks.includes(i)?'checked':''}><span>${t}</span></label>`).join('')}</section><section class="card content-card"><h3>Dentro del kit</h3><p>${L('Abre una guía paso a paso en otra pestaña. Puedes copiar los comandos e imprimir o guardar en PDF.','Open a step-by-step guide in a new tab. Copy commands and print or save as PDF.')}</p>${kitItems.map(item=>`<a class="file-link" href="/kit.html?file=${encodeURIComponent(item.file)}&lang=${language}&host=${hostPlatform()}" target="_blank" rel="noopener">${icon('book')}${item[language]}${icon('external')}</a>`).join('')}<p class="small muted">Revisa espacio libre para dos discos virtuales, snapshots, imágenes y runtimes. Este entorno de construcción no ha arrancado las VMs en tu hipervisor.</p></section></aside></div>`}
async function loadVagrantfile(){try{const response=await fetch('/lab/Vagrantfile');if(!response.ok)throw Error('Archivo no disponible');const text=await response.text();const node=document.querySelector('#vagrant-source');if(node)node.textContent=text}catch{const node=document.querySelector('#vagrant-source');if(node)node.textContent='No se pudo cargar. Descarga el archivo desde el enlace.'}}
function progress(){const done=completed();return `${pageHeading('CADA INTENTO CUENTA','Tu progreso','Completar significa cumplir los criterios y dejar evidencia.',btn(icon('upload')+' Restaurar respaldo','import-backup','secondary'))}<section class="progress-top card"><div class="progress-ring" style="--p:${done.size/labs.length*100}%"><span>${Math.round(done.size/labs.length*100)}<small>%</small></span></div><div><span class="eyebrow">COBERTURA DEL CATÁLOGO</span><h2>${done.size} de ${labs.length} laboratorios completados</h2><p>${state.history.length} sesiones finalizadas · ${formatTime(totalTime())} de práctica acumulada</p><small class="muted">Incluye verificación local y autoevaluación, según el criterio. No equivale a una certificación.</small></div></section><div class="progress-grid">${domains.map(d=>{const inDomain=labs.filter(l=>l.domain===d[0]),n=inDomain.filter(l=>done.has(l.id)).length;return `<article class="card domain-progress"><div><strong>${d[1]}</strong><span>${n}/${inDomain.length}</span></div><div class="bar"><i style="width:${n/inDomain.length*100}%"></i></div><small>${d[2]}</small></article>`}).join('')}</div><div class="section-title"><div><h2>Historial de sesiones</h2><p>Consulta lo que comprobaste y lo que puedes reforzar.</p></div>${btn('Exportar respaldo','export','text')}</div>${state.history.length?`<div class="history-list">${state.history.map((h,i)=>`<button class="card history-row" data-action="results" data-index="${i}"><span class="box-icon">${icon(h.mode==='exam'?'clock':'terminal')}</span><span><strong>${h.mode==='exam'?'Simulacro':exercises.find(l=>l.id===h.labs[0])?.title}</strong><small>${date(h.finishedAt)} · ${formatTime(h.elapsed)} ${h.timedOut?'· Tiempo agotado':''}</small></span><span class="pill ${h.completed.length===h.labs.length?'success':''}">${h.mode==='exam'&&h.examVersion>=4&&h.verification?.status!=='compared'?'Verificación pendiente':h.mode==='exam'&&h.examVersion>=4?scoreExam(h).total+'/300 · '+h.completed.length+'/'+h.labs.length:h.completed.length+'/'+h.labs.length+' completos'}</span>${icon('chevron')}</button>`).join('')}</div>`:`<div class="empty card"><h3>Tu historial empieza con el primer intento</h3><p>El catálogo está abierto. Escoge el reto que necesitas hoy.</p><a href="#catalog" class="btn secondary">Elegir laboratorio ${icon('arrow')}</a></div>`}<div class="info-strip">${icon('lock')} El progreso se guarda en tu perfil. Cada usuario tiene su propia bitácora, historial y prácticas. Los respaldos JSON siguen disponibles.</div>`}
function journal(){const entries=state.history.flatMap(h=>h.labs.filter(id=>h.work[id]?.notes).map(id=>({lab:exercises.find(l=>l.id===id),note:h.work[id].notes,at:h.finishedAt})));return `${pageHeading('DE LA EXPERIENCIA AL CRITERIO','Tu bitácora','Síntoma, hipótesis, causa y reparación: el conocimiento que te llevas.',btn(icon('download')+' Exportar bitácora','export-journal','secondary'))}<div class="card content-card journal-new"><h2>Captura un aprendizaje</h2><label class="evidence-label" for="journal-title">Título</label><input id="journal-title" placeholder="Una avería, una duda o algo que aprendiste…" maxlength="150"><label class="evidence-label" for="journal-body">Tu nota</label><textarea id="journal-body" rows="5" placeholder="Síntoma → hipótesis → evidencia → causa → reparación → prueba final"></textarea>${btn('Guardar nota '+icon('check'),'save-note')}</div><div class="section-title"><h2>Conocimiento registrado <span class="muted">${entries.length+state.journal.length}</span></h2></div><div class="journal-grid">${state.journal.map((j,i)=>`<article class="card content-card"><div class="card-overline"><span class="badge">NOTA PERSONAL</span><small>${date(j.at)}</small></div><h3 data-user-content>${esc(j.title)}</h3><p class="preserve">${esc(j.body)}</p>${btn('Eliminar nota','delete-note','text small',`data-index="${i}"`)}</article>`).join('')}${entries.map(e=>`<article class="card content-card"><div class="card-overline"><span class="badge">${domain(e.lab.domain)}</span><small>${date(e.at)}</small></div><h3>${e.lab.title}</h3><p class="preserve">${esc(e.note)}</p></article>`).join('')}</div>${entries.length+state.journal.length===0?'<div class="empty"><h3>No dejes que un buen diagnóstico se pierda.</h3><p>Las notas de tus sesiones finalizadas aparecerán aquí.</p></div>':''}`}
function resources(){return `${pageHeading('INVESTIGA. CONTRASTA. PRACTICA.','Tu biblioteca de referencia','Empieza por documentación oficial y aprende a encontrar ayuda dentro del sistema.')}<div class="resource-banner card"><span class="box-icon">${icon('book')}</span><div><h2>Objetivos oficiales EX200</h2><p>Alcance oficial de RHEL 10 revisado el 17 de noviembre de 2026; laboratorio sobre Rocky Linux 10. Flatpak figura en EX200. Podman se incluye como extensión y no aparece en la lista actual. Los escenarios son originales.</p><a href="https://www.redhat.com/en/services/training/ex200-red-hat-certified-system-administrator-rhcsa-exam" target="_blank" rel="noopener">Consultar alcance oficial ${icon('external')}</a></div></div><div class="resource-grid">${domains.map(d=>`<section class="card content-card"><span class="eyebrow">${d[1]}</span><h3>${d[2]}</h3><p class="small">${esc(exercises.find(l=>l.domain===d[0]).learning.concept)}</p><ul class="reading-list">${[...new Set(labs.filter(l=>l.domain===d[0]).flatMap(l=>l.reading))].map(r=>`<li>${icon('book')}${r.startsWith('http')?`<a href="${r}" target="_blank" rel="noopener">Documentación técnica ${icon('external')}</a>`:`<code>${r}</code>`}</li>`).join('')}</ul></section>`).join('')}</div><div class="info-strip">${icon('book')} En cada manual busca DESCRIPCIÓN, OPCIONES, EJEMPLOS y VÉASE TAMBIÉN. Durante el simulacro, usa la documentación instalada en tus VMs.</div>`}
function openModal(html){modalFocus=document.activeElement;document.querySelector('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="Información de la sesión"><button class="modal-close" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button>${html}</section></div>`;document.querySelector('.modal button')?.focus()}
function closeModal(){document.querySelector('#modal-root').innerHTML='';modalFocus?.isConnected&&modalFocus.focus()}
function download(name,body,type='application/json'){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function updateClock(){const s=state.session,c=document.querySelector('#clock');if(c&&s){c.textContent=formatTime(remaining(s));c.classList.toggle('urgent',remaining(s)<300000)}}
document.addEventListener('click',async e=>{if(e.target.closest('.skip')){e.preventDefault();document.querySelector('#main').focus();return}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,s=state.session,l=s&&currentLab();if(s?.mode==='exam'&&remaining(s)<=0){finishSession(true);return}switch(a){case 'pair-agent':await pairAgent();break;case 'verify-vms':closeModal();await verifyAttempt(state.history.find(h=>h.id===b.dataset.id));break;case 'copy-guide-command':try{await navigator.clipboard.writeText(commandGuide[Number(b.dataset.index)].command);toast('Comando de ejemplo copiado.')}catch{toast('Selecciona y copia el comando.')}break;case 'disconnect-agent':if(!agentBusy){agentToken='';agentConnected=false;agentMessage='Agente desconectado de esta pestaña.';render()}break;case 'auth-mode':if(authMode==='login'&&registrationMode==='closed'){toast('El administrador mantiene cerrado el registro.');break}authMode=authMode==='login'?'register':'login';render();break;case 'independence':openModal(`<h2>Guía independiente de preparación</h2><p>${independence()}</p>`);break;case 'logout':if(agentBusy){toast('Espera a que termine la validación de las VMs.');break}try{await flushSync();await apiFetch('/api/logout','POST',{});profile=null;state=fresh();agentToken='';agentConnected=false;render()}catch(e){toast(e.message)}break;case 'import-legacy':if(legacy?.version===1&&Array.isArray(legacy.history)){state=legacy;persist();render();toast('Progreso anterior asignado a tu perfil.')}break;case 'platform':if(hostGuides[b.dataset.host]){state.hostPlatform=b.dataset.host;persist();render()}break;case 'copy-vagrant':try{const r=await fetch('/lab/Vagrantfile');if(!r.ok)throw Error();await navigator.clipboard.writeText(await r.text());toast('Vagrantfile copiado.')}catch{toast('Descarga el Vagrantfile desde el enlace.')}break;case 'start-next':start([(labs.find(x=>!completed().has(x.id))||labs[0]).id],'practice');break;case 'start-lab':start([b.dataset.id],'practice');break;case 'resume-route':location.hash='session';break;case 'confirm-exam':openModal(`<span class="eyebrow">ANTES DE EMPEZAR</span><h2>¿Listo para 02:00:00 exactas?</h2><p>Son 32 retos y 62 objetivos. Prepara VMs, discos, repositorios, verificador y snapshots antes de empezar. El reloj no tiene pausa y mantiene la fecha límite al cerrar o recargar.</p><p>Puedes saltar cualquier reto, marcarlo para revisar y volver después. Al agotarse las dos horas se cierra el trabajo. Después, el agente lee ambas VMs, reinicia normalmente las dos y vuelve a leerlas para comprobar persistencia. Esa validación no amplía las dos horas de práctica. Las referencias y la retroalimentación se muestran al finalizar.</p><div class="modal-actions">${btn('Iniciar simulacro','start-exam')}${btn('Seguir preparando','close-modal','secondary')}</div>`);break;case 'start-exam':closeModal();start(examLabs,'exam');break;case 'pause':if(s?.mode==='practice'&&s.status==='running'){s.elapsed=elapsed(s);s.status='paused';persist();render()}break;case 'unpause':if(s?.status==='paused'){s.status='running';s.runningSince=Date.now();persist();render()}break;case 'phase':if(s?.status==='running'){work(l).phase=Number(b.dataset.phase);persist();render()}break;case 'hint':if(s?.mode==='practice'&&s.status==='running'){work(l).hints=Math.min(3,work(l).hints+1);persist();render()}break;case 'select-lab':if(selectExamTask(s,b.dataset.id)){selected=b.dataset.id;persist();render()}break;case 'exam-next':case 'exam-previous':case 'exam-skip':if(s?.mode==='exam'){selected=navigateExam(s,a==='exam-previous'?'previous':a==='exam-skip'?'skip':'next');persist();render();document.querySelector('.session-header')?.scrollIntoView({block:'start'})}break;case 'exam-review':if(s?.mode==='exam'&&s.status==='running'){const w=work(l);w.review=!w.review;if(!w.review)w.skipped=false;persist();render()}break;case 'exam-ready':if(s?.mode==='exam'&&s.status==='running'){const w=work(l);w.ready=!w.ready;if(w.ready){w.review=false;w.skipped=false}persist();render()}break;case 'finish':if(s)openModal(`<span class="eyebrow">CERRAR ESTE INTENTO</span><h2>¿Finalizar la sesión?</h2><p>Se guardarán tu tiempo y evidencia. Los criterios pendientes quedarán para reforzar. Puedes repetir el laboratorio en otro intento.</p><div class="modal-actions">${btn('Finalizar y ver resultados','confirm-finish')}${btn('Seguir practicando','close-modal','secondary')}</div>`);break;case 'confirm-finish':closeModal();finishSession();break;case 'evaluate':toast(feedback(l,work(l)));render();break;case 'import-report':if(s?.status==='running')document.querySelector('#report-file').click();else toast('Reanuda la sesión para importar.');break;case 'copy-command':try{await navigator.clipboard.writeText(`${collectCommand(s)}`);toast('Comando copiado. Ejecútalo desde la carpeta del kit en tu equipo.')}catch{toast('Selecciona y copia el comando de la sesión.')}break;case 'export':download(`rhcsa-respaldo-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify({kind:'rhcsa-backup',schema:1,exportedAt:new Date().toISOString(),state},null,2));toast('Respaldo exportado.');break;case 'import-backup':if(state.session){toast('Finaliza la sesión antes de restaurar un respaldo.');break}document.querySelector('#backup-file').click();break;case 'clear-filters':search='';filter=statusFilter='all';render();break;case 'results':if(state.session?.mode==='exam'){toast('Finaliza el simulacro para consultar la retroalimentación.');break}openResults(state.history[Number(b.dataset.index)]);break;case 'close-modal':closeModal();break;case 'save-note':{const title=document.querySelector('#journal-title').value.trim(),body=document.querySelector('#journal-body').value.trim();if(!title||body.length<20){toast('Añade un título y una nota de al menos 20 caracteres.');break}state.journal.unshift({title,body,at:Date.now()});persist();render();toast('Aprendizaje guardado.');break}case 'delete-note':openModal(`<h2>¿Eliminar esta nota?</h2><p>Esta nota personal se eliminará de tu perfil.</p><div class="modal-actions">${btn('Eliminar nota','confirm-delete','primary',`data-index="${b.dataset.index}"`)}${btn('Conservar','close-modal','secondary')}</div>`);break;case 'confirm-delete':state.journal.splice(Number(b.dataset.index),1);persist();closeModal();render();break;case 'export-journal':{const lines=['# Bitácora Linux Lab','',...state.journal.flatMap(j=>[`## ${j.title}`,date(j.at),'',j.body,'']),...state.history.flatMap(h=>h.labs.filter(id=>h.work[id]?.notes).flatMap(id=>[`## ${exercises.find(l=>l.id===id).title}`,date(h.finishedAt),'',h.work[id].notes,'']))];download('bitacora-rhcsa.md',lines.join('\n'),'text/markdown');break}}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='search'){search=t.value;updateCatalog()}if(t.id==='command-search'){commandSearch=t.value;updateCommands()}const s=state.session;if(s?.mode==='exam'&&remaining(s)<=0){finishSession(true);return}if(s?.status==='running'){const w=work(currentLab());if(t.hasAttribute('data-evidence')){w.evidence[t.dataset.evidence]=t.value;persist()}if(t.id==='session-notes'){w.notes=t.value;persist()}}});
document.addEventListener('change',e=>{const t=e.target;if(state.session?.mode==='exam'&&remaining(state.session)<=0){finishSession(true);return}if(t.id==='exam-jump'&&selectExamTask(state.session,t.value)){selected=t.value;persist();render()}if(t.id==='command-area'){commandArea=t.value;updateCommands()}if(t.id==='domain-filter'){filter=t.value;updateCatalog()}if(t.id==='status-filter'){statusFilter=t.value;updateCatalog()}if(t.hasAttribute('data-vm')){const n=Number(t.dataset.vm);state.vmChecks=t.checked?[...new Set([...state.vmChecks,n])]:state.vmChecks.filter(x=>x!==n);persist()}if(t.hasAttribute('data-manual')&&state.session?.status==='running'){work(currentLab()).manual[t.dataset.manual]=t.checked;persist()} });
document.querySelector('#report-file').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>1000000)throw Error('El informe supera 1 MB.');const data=JSON.parse(await f.text());const results=parseReport(data,state.session,exercises.map(l=>l.id));for(const r of results){const target=exercises.find(l=>l.id===r.lab);if(!target.auto.includes(r.criterion)||r.machine!==(target.machine==='ambas'?'client':target.machine))throw Error('Criterio o máquina fuera del contrato del verificador.')}for(const r of results){const w=work(exercises.find(l=>l.id===r.lab));w.checks[r.criterion]={pass:r.pass,detail:r.detail.slice(0,1000),machine:r.machine,at:Date.parse(data.generatedAt)}}persist();render();toast(state.session.mode==='exam'?'Informe recibido. Resultados disponibles al finalizar.':`${results.length} comprobaciones locales importadas.`)}catch(err){toast('No se importó: '+err.message)}});
let pendingBackup;
document.querySelector('#backup-file').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>5000000)throw Error('El respaldo supera 5 MB.');const d=JSON.parse(await f.text());const ids=exercises.map(l=>l.id);if(d.kind!=='rhcsa-backup'||d.schema!==1||d.state?.version!==1||d.state.session!==null||!Array.isArray(d.state.history)||!Array.isArray(d.state.journal)||!Array.isArray(d.state.vmChecks))throw Error('Usa un respaldo válido sin sesión activa.');for(const h of d.state.history){if(!Array.isArray(h.labs)||!h.labs.length||!h.labs.every(id=>ids.includes(id))||!h.work||!Array.isArray(h.completed)||!h.completed.every(id=>h.labs.includes(id))||!Number.isFinite(h.elapsed)||!Number.isFinite(h.finishedAt))throw Error('Historial incompatible.')}if(d.state.journal.some(j=>typeof j.title!=='string'||typeof j.body!=='string'||!Number.isFinite(j.at))||d.state.vmChecks.some(n=>!Number.isInteger(n)||n<0||n>5))throw Error('Datos incompatibles.');pendingBackup=d.state;openModal(`<h2>¿Restaurar este respaldo?</h2><p>Reemplazará el progreso de tu perfil por ${d.state.history.length} sesiones y ${d.state.journal.length} notas. Exporta tu estado actual si quieres conservarlo.</p><div class="modal-actions">${btn('Restaurar respaldo','restore-confirm')}${btn('Cancelar','close-modal','secondary')}${btn('Exportar actual','export','text')}</div>`)}catch(err){toast('No se restauró: '+err.message)}});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="restore-confirm"]')&&pendingBackup&&!state.session){state=pendingBackup;pendingBackup=null;persist();closeModal();render();toast('Respaldo restaurado.')}});
document.addEventListener('keydown',e=>{const modal=document.querySelector('.modal');if(!modal)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const focusable=[...modal.querySelectorAll('button:not([disabled]),a,input,textarea,summary')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
const originalRender=render;render=function(){originalRender();if(profile&&route()==='catalog')updateCatalog();if(profile&&route()==='vms')loadVagrantfile();if(profile&&route()==='commands')updateCommands()};
document.addEventListener('submit',e=>{if(e.target.id==='profile-form'){e.preventDefault();handleAuth()}if(e.target.id==='agent-form'){e.preventDefault();pairAgent()}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&profile&&dirty)flushSync().catch(()=>{})});

function criterionPoints(id,index){return rubric.flatMap(a=>a.tasks).find(t=>t.id===id)?.criteria[index]?.max||0;}
function scorePanel(attempt){const grade=scoreExam(attempt);return `<section class="score-panel card content-card"><span class="eyebrow">${L('RÚBRICA DE ENTRENAMIENTO · 300 PUNTOS','TRAINING RUBRIC · 300 POINTS')}</span><h2>${grade.verified?grade.total:'—'} <small>/ 300</small></h2><p>${grade.verified?L('Puntuación final de este intento.','Final score for this attempt.'):L('Puntuación pendiente: primero se deben comparar las dos VMs tras el reinicio.','Score pending: both VMs must be compared after reboot first.')}</p><p>${L('Puntos técnicos','Technical points')}: <strong>${grade.technical}</strong> · ${L('Puntos documentales / autoevaluación','Documentary / self-assessed points')}: <strong>${grade.documentary}</strong></p><div class="score-areas">${grade.areas.map(a=>`<div><span>${esc(translateText(domain(a.domain)))}</span><strong>${grade.verified?a.earned:'—'}/30</strong><div class="bar"><i style="width:${a.earned/30*100}%"></i></div></div>`).join('')}</div><p class="small muted">${L('Rúbrica propia: 30 puntos por área, con crédito parcial por criterio. Preparado no suma puntos. Los criterios documentales requieren la evidencia registrada antes del cierre. No es la rúbrica ni una calificación oficial de Red Hat.','Custom rubric: 30 points per area, with partial credit per criterion. Ready marks award no points. Documentary checks require evidence recorded before finishing. This is not Red Hat’s rubric or an official grade.')}</p></section>`;}
function rubricView(){return `<section class="card content-card"><span class="eyebrow">${L('PUNTUACIÓN TRANSPARENTE','TRANSPARENT SCORING')}</span><h2>300 ${L('puntos · 10 áreas','points · 10 areas')}</h2><p>${L('Cada área vale 30 puntos. Puedes obtener crédito parcial por criterio; sus pesos se muestran abajo y durante el reto. El resultado final requiere la recolección y comparación de ambas VMs.','Each area is worth 30 points. Partial credit is available per criterion; weights are shown below and during the task. Final scoring requires collecting and comparing both VMs.')}</p><details><summary>${L('Ver distribución por concepto, reto y criterio','View weights by area, task and criterion')}</summary>${rubric.map(a=>`<h3>${esc(translateText(domain(a.domain)))} · 30 ${L('puntos','points')}</h3><div class="table-scroll"><table><thead><tr><th>${L('Reto','Task')}</th><th>${L('Criterios 1 / 2 / 3','Criteria 1 / 2 / 3')}</th><th>${L('Máximo','Maximum')}</th></tr></thead><tbody>${a.tasks.map(t=>`<tr><td>${esc(translateText(exercises.find(l=>l.id===t.id).title))}</td><td>${t.criteria.map(c=>c.max).join(' / ')}</td><td>${t.max}</td></tr>`).join('')}</tbody></table></div>`).join('')}</details><p class="small muted">${L('Distribución propia de esta guía. No reproduce la puntuación ni el umbral de aprobación del examen oficial.','This guide uses its own distribution. It does not reproduce the official exam’s scoring or passing threshold.')}</p></section>`;}
const baseExamView=exam;exam=function(){return baseExamView()+rubricView();};
function openReadingLinks(root=document){for(const a of root.querySelectorAll('a[href^="/lab/"]')){const name=decodeURIComponent(new URL(a.href,location.origin).pathname.split('/').at(-1));if(!kitItems.some(i=>i.file===name))continue;a.href='/kit.html?file='+encodeURIComponent(name)+'&lang='+language+'&host='+hostPlatform();a.target='_blank';a.rel='noopener';a.removeAttribute('download');for(const node of a.childNodes)if(node.nodeType===3)node.textContent=node.textContent.replace('Descargar','Leer').replace('Download','Read');}}
const localizedRender=render;render=function(){localizedRender();const actions=document.querySelector('.top-actions');if(actions&&!actions.querySelector('.language-control'))actions.insertAdjacentHTML('afterbegin',languageControl());if(!profile){const auth=document.querySelector('.auth-page');if(auth&&!auth.querySelector('.language-control'))auth.insertAdjacentHTML('afterbegin','<div class="auth-language">'+languageControl()+'</div>');}document.documentElement.lang=language;const skip=document.querySelector('.skip');if(skip)skip.textContent=L('Ir al contenido','Skip to content');document.title=L('Linux Lab · Guía independiente de preparación EX200','Linux Lab · Independent EX200 preparation guide');openReadingLinks();translateDOM(document.body);};
document.addEventListener('click',event=>{const button=event.target.closest('[data-language]');if(!button)return;setLanguage(button.dataset.language);if(document.querySelector('.modal'))closeModal();render();});
const localizedToast=toast;toast=function(text){localizedToast(translateText(text));};
const localizedModal=openModal;openModal=function(html){localizedModal(html);openReadingLinks();translateDOM(document.querySelector('#modal-root'));};
let translating=false;const translationObserver=new MutationObserver(records=>{if(translating||language!=='en')return;if(!records.some(r=>!r.target.parentElement?.closest('code,pre,textarea,.preserve,.attempt-id')))return;translating=true;translateDOM(document.body);translationObserver.takeRecords();translating=false;});translationObserver.observe(document.body,{childList:true,subtree:true,characterData:true});

setInterval(()=>{if(profile&&!expire())updateClock()},500);render();bootstrap();

// Appended to the standalone app module by build-portable.mjs.
let accountSearch='',accountInactiveDays='0',accountRows=[],accountLoad=0,deletionPreviewData=null;
function accountsView(){if(profile?.role!=='admin')return '<div class="empty card"><h1>Acceso restringido</h1></div>';return `${pageHeading('ADMINISTRACIÓN MANUAL','Cuentas y actividad','Revisa la última actividad y decide qué cuentas conservar. No hay eliminación automática.')}<section class="card content-card"><form id="accounts-filter"><label for="account-search">Usuario</label><input id="account-search" maxlength="32" value="${esc(accountSearch)}" placeholder="Buscar por nombre"><label for="account-inactive">Sin actividad desde hace</label><select id="account-inactive">${[['0','Mostrar todas'],['30','30 días'],['60','60 días'],['90','90 días'],['180','180 días'],['365','Un año']].map(([value,label])=>`<option value="${value}" ${accountInactiveDays===value?'selected':''}>${label}</option>`).join('')}</select><button type="submit" class="btn secondary">Aplicar filtro</button></form><p id="accounts-message" role="status">Cargando cuentas…</p><div id="accounts-list"></div></section><div class="info-strip">Cada borrado muestra primero la cuenta, su última actividad y cuántas sesiones de práctica, notas personales e informes desaparecerán. El nombre debe escribirse exactamente. Una cuenta con actividad nueva requiere otra revisión. Las cuentas administradoras están protegidas.</div>`;}
async function loadAccounts(){const request=++accountLoad,node=document.querySelector('#accounts-list');if(!node||profile?.role!=='admin')return;try{const result=await apiFetch(`/api/admin/users?inactiveDays=${encodeURIComponent(accountInactiveDays)}&search=${encodeURIComponent(accountSearch)}`);if(request!==accountLoad||!node.isConnected)return;accountRows=result.users;document.querySelector('#accounts-message').textContent=`${result.users.length} cuenta(s). Se muestran hasta ${result.limit}, ordenadas desde la menor actividad.`;node.innerHTML=`<div class="table-scroll"><table class="command-table"><thead><tr><th>Usuario</th><th>Última actividad</th><th>Intentos</th><th>Notas</th><th>Informes</th><th>Acción</th></tr></thead><tbody>${result.users.map(u=>`<tr><td><strong>${esc(u.username)}</strong><br><small>${u.role==='admin'?'Administrador':'Estudiante'}</small></td><td>${date(u.last_seen_at)}<br><small>${Math.max(0,Math.floor((Date.now()-u.last_seen_at)/86400000))} días sin actividad</small></td><td>${u.attempts}</td><td>${u.notes}</td><td>${u.reports}</td><td>${u.role==='user'?btn('Revisar borrado','admin-delete-preview','secondary small',`data-id="${u.id}"`):'<span class="pill">Protegida</span>'}</td></tr>`).join('')}</tbody></table></div>${result.users.length?'':'<p>No hay cuentas que coincidan con el filtro.</p>'}`;}catch(e){const message=document.querySelector('#accounts-message');if(message)message.textContent=e.message;}}
async function showDeletionPreview(id){try{const result=await apiFetch(`/api/admin/delete-preview?id=${encodeURIComponent(id)}`);deletionPreviewData=result;const u=result.target;openModal(`<span class="eyebrow">ELIMINACIÓN DEFINITIVA · REVISIÓN OBLIGATORIA</span><h2>Revisa la cuenta ${esc(u.username)}</h2><p>Última actividad: <strong>${date(u.last_seen_at)}</strong>.</p><p>Se borrarán su perfil, contraseñas protegidas, sesiones de acceso, progreso, bitácoras y evidencia de las VMs: <strong>${u.attempts} intento(s), ${u.notes} nota(s) personal(es) y ${u.reports} informe(s)</strong>. Las notas dentro de los intentos también se eliminan. Esta acción no tiene papelera. El registro administrativo conserva solo el evento, identificadores internos y cantidades.</p><label class="evidence-label" for="delete-confirm-user">Escribe ${esc(u.username)} para confirmar</label><input id="delete-confirm-user" autocomplete="off" spellcheck="false" maxlength="32"><p id="delete-error" role="alert"></p><div class="modal-actions">${btn('Eliminar definitivamente','admin-delete-confirm','primary')}${btn('Conservar cuenta','close-modal','secondary')}</div><p class="small muted">La revisión vence en 10 minutos y exige una sesión de administrador iniciada en los últimos 15 minutos.</p>`);}catch(e){toast(e.message);}}
document.addEventListener('submit',e=>{if(e.target.id==='accounts-filter'){e.preventDefault();accountSearch=document.querySelector('#account-search').value.trim();accountInactiveDays=document.querySelector('#account-inactive').value;loadAccounts();}});
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button||button.disabled)return;if(button.dataset.action==='admin-delete-preview')await showDeletionPreview(button.dataset.id);if(button.dataset.action==='admin-delete-confirm'&&deletionPreviewData){const {target,token}=deletionPreviewData,confirmation=document.querySelector('#delete-confirm-user').value;if(confirmation!==target.username){document.querySelector('#delete-error').textContent='Escribe exactamente el nombre de usuario indicado.';return;}button.disabled=true;try{await apiFetch('/api/admin/delete','POST',{id:target.id,token,confirmation});deletionPreviewData=null;closeModal();render();toast('Cuenta y datos asociados eliminados.');}catch(error){const node=document.querySelector('#delete-error');if(node)node.textContent=error.message;}finally{button.disabled=false;}}});
const standaloneRender=render;render=function(){standaloneRender();if(profile&&route()==='accounts')loadAccounts();};
